import{_ as t,c as r,o as a,a2 as e}from"./chunks/framework.Ja7AKUN6.js";const u=JSON.parse('{"title":"2026 年 11 月更新：新成员加入 准入条款修订 招募新成员","description":"","frontmatter":{"title":"2026 年 11 月更新：新成员加入 准入条款修订 招募新成员","contributors":["kegongteng","daizihan233"],"date":"2026-11-14T00:00:00.000Z","updated":"2026-11-14T00:00:00.000Z","categories":"博客更新","tags":["公告","人事变动"]},"headers":[],"relativePath":"blog/202611.md","filePath":"blog/202611.md"}'),o={name:"blog/202611.md"},n=e('<h1 id="_2026-年-11-月更新-新成员加入-准入条款修订-招募新成员" tabindex="-1">2026 年 11 月更新：新成员加入 准入条款修订 招募新成员 <a class="header-anchor" href="#_2026-年-11-月更新-新成员加入-准入条款修订-招募新成员" aria-label="Permalink to &quot;2026 年 11 月更新：新成员加入 准入条款修订 招募新成员&quot;">​</a></h1><h2 id="新成员加入" tabindex="-1">新成员加入 <a class="header-anchor" href="#新成员加入" aria-label="Permalink to &quot;新成员加入&quot;">​</a></h2><p>近期，<a href="https://github.com/daizihan233" target="_blank" rel="noreferrer">KuoHu</a>、<a href="https://github.com/CarmJos" target="_blank" rel="noreferrer">CarmJos</a>和<a href="https://github.com/ltzXiaoYanMo" target="_blank" rel="noreferrer">YanMo2333</a>加入了开往维护组。他们将发挥所长，参与开往项目相关工具的开发与常规维护工作，为开往注入新动力。</p><h2 id="准入条款修订" tabindex="-1">准入条款修订 <a class="header-anchor" href="#准入条款修订" aria-label="Permalink to &quot;准入条款修订&quot;">​</a></h2><p>开往维护组于 2026 年 7 月发布了审核工作意见征集，该组外征集在 2026 年 10 月 1 号截止。根据征集意见，我们修订了新准入条款，具体变动如下：</p><ol><li><p>增加非全年龄内容倡议：<strong>倡导</strong>对边缘性非全年龄内容采取相应措施，兼顾公共展示环境及全年龄用户的观感，以确保使用者的体验。</p></li><li><p>明确巡查处理：根据《开往项目运维规定》，维护组有权通知成员进行整改，并在通知后执行删除操作。本次准入条款修订中，<strong>明确</strong>具体处置流程，以便提前知悉相关规定。</p></li><li><p>完善非博客类站点的说明：对于<strong>非博客类网站</strong>，您仍可提交加入开往的申请，但此类申请有较大概率无法通过，申请人可以依据运维规定要求维护组重审。</p></li><li><p>删除 eTLD 条款：现在开往对<strong>所有域名</strong>都保留在<strong>极端情况</strong>下先删除后通知的权利</p></li><li><p>修改对文章数量的要求：至少 10 篇<strong>原创文章</strong>，且原创文章<strong>不应低于</strong>文章总数的 70%，AI 文不计入原创文章，但计入文章总数。</p></li><li><p>明确可访问性要求：要求网站的访问时长在自动巡查中<strong>不应</strong>超时，在人工巡查时<strong>不宜</strong>过长。</p></li><li><p>明确自动通知条件：开往的巡查机器人在满足<strong>特定条件</strong>时会向站长发送提醒，该提醒<strong>同时视为</strong>警告与限期整改邮件。</p></li></ol><h2 id="开往需要新鲜血液" tabindex="-1">开往需要新鲜血液 <a class="header-anchor" href="#开往需要新鲜血液" aria-label="Permalink to &quot;开往需要新鲜血液&quot;">​</a></h2><p>开往维护组目前负责的巡查组工具、跳转功能和成员列表在开发与使用中暴露出一些问题，部分功能与实际需求不符，影响了日常维护效率和成员使用体验。为梳理需求、修复问题并推进迭代，现面向社区招募新成员加入维护组。要求擅长 TypeScript、Go、Vue、Python、Node.js 中任一技术栈，并具备责任心、沟通协作等基础品质。欢迎愿意用技术为开往社区做事的伙伴申请加入，一起把这些工具做得更可靠、更贴合实际需求。</p><p>如果您对于参与项目组感兴趣，请致信 <a href="mailto:project@travellings.cn" target="_blank" rel="noreferrer">project@travellings.cn</a></p>',9),s=[n];function l(i,p,g,h,c,_){return a(),r("div",null,s)}const f=t(o,[["render",l]]);export{u as __pageData,f as default};
